namespace sv_3b2221ff38c14061983f9a4602c61e13.Services;

/// <summary>
/// Scoped service (one per circuit) that holds the currently selected warehouse
/// and notifies all subscribed components when the selection changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
        ("WH-D", "Warehouse D"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_3b2221ff38c14061983f9a4602c61e13.Services;

/// <summary>
/// Scoped service (one per circuit) that polls for low-stock alerts
/// and broadcasts the latest count to all subscribed components.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever a new alert count is fetched. All subscribed components
    /// (regardless of their position in the tree) receive this notification.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Registers a subscriber and starts polling if this is the first one.
    /// Components call this in OnInitialized / OnAfterRender.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;

        if (_subscriberCount == 1)
            BeginPollingLoop();
    }

    /// <summary>
    /// Unregisters a subscriber and stops polling when the last one leaves.
    /// Components call this in Dispose.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
            CancelPollingLoop();
    }

    private void BeginPollingLoop()
    {
        CancelPollingLoop();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            // Fetch immediately on start, then every 10 s.
            await FetchAndNotifyAsync();

            try
            {
                while (await _timer.WaitForNextTickAsync(token))
                {
                    await FetchAndNotifyAsync();
                }
            }
            catch (OperationCanceledException) { /* expected on stop */ }
        });
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task OnWarehouseChangedAsync()
    {
        // When the warehouse changes, fetch fresh data immediately.
        await FetchAndNotifyAsync();
    }

    private void CancelPollingLoop()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChangedAsync;
        CancelPollingLoop();
    }
}

