@using sv_3b2221ff38c14061983f9a4602c61e13.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            await WarehouseState.SetWarehouseAsync(warehouseId);
        }
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@using sv_3b2221ff38c14061983f9a4602c61e13.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    /// <summary>
    /// When true, this instance participates in the polling lifecycle
    /// (starts polling on init, stops on dispose). Only the dashboard
    /// page instance should set this. Sidebar badges piggyback on the
    /// polling without controlling it.
    /// </summary>
    [Parameter] public bool ControlsPolling { get; set; }

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;

        if (ControlsPolling)
            AlertService.StartPolling();
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;

        if (ControlsPolling)
            AlertService.StopPolling();
    }
}

